SET NOCOUNT ON;
SET XACT_ABORT ON;
IF OBJECT_ID('dbo.__Phase2ReportingBackup') IS NULL THROW 51021,'Reporting rollback snapshot is missing.',1;
IF HASHBYTES('SHA2_256',COALESCE((SELECT * FROM dbo.Modules WHERE ModuleName IN ('Reporting','Reports') ORDER BY ModuleId FOR JSON PATH, INCLUDE_NULL_VALUES),N'[]')) <> (SELECT HASHBYTES('SHA2_256',AfterJson) FROM dbo.__Phase2ReportingBackup WHERE ObjectName='Modules') THROW 51021,'Reporting metadata changed after consolidation; manual reconciliation required before rollback.',1;
IF HASHBYTES('SHA2_256',COALESCE((SELECT * FROM dbo.RoleModules WHERE ModuleId IN (SELECT ModuleId FROM dbo.Modules WHERE ModuleName IN ('Reporting','Reports')) ORDER BY RoleModuleId FOR JSON PATH, INCLUDE_NULL_VALUES),N'[]')) <> (SELECT HASHBYTES('SHA2_256',AfterJson) FROM dbo.__Phase2ReportingBackup WHERE ObjectName='RoleModules') THROW 51021,'Reporting metadata changed after consolidation; manual reconciliation required before rollback.',1;
IF HASHBYTES('SHA2_256',COALESCE((SELECT * FROM dbo.RoleModulePermissions WHERE RoleModuleId IN (SELECT RoleModuleId FROM dbo.RoleModules WHERE ModuleId IN (SELECT ModuleId FROM dbo.Modules WHERE ModuleName IN ('Reporting','Reports'))) ORDER BY RoleModulePermissionId FOR JSON PATH, INCLUDE_NULL_VALUES),N'[]')) <> (SELECT HASHBYTES('SHA2_256',AfterJson) FROM dbo.__Phase2ReportingBackup WHERE ObjectName='RoleModulePermissions') THROW 51021,'Reporting metadata changed after consolidation; manual reconciliation required before rollback.',1;
IF HASHBYTES('SHA2_256',COALESCE((SELECT * FROM dbo.FarmHouseModules WHERE ModuleId IN (SELECT ModuleId FROM dbo.Modules WHERE ModuleName IN ('Reporting','Reports')) ORDER BY FarmHouseModuleId FOR JSON PATH, INCLUDE_NULL_VALUES),N'[]')) <> (SELECT HASHBYTES('SHA2_256',AfterJson) FROM dbo.__Phase2ReportingBackup WHERE ObjectName='FarmHouseModules') THROW 51021,'Reporting metadata changed after consolidation; manual reconciliation required before rollback.',1;
DELETE FROM dbo.RoleModulePermissions WHERE RoleModuleId IN (SELECT RoleModuleId FROM dbo.RoleModules WHERE ModuleId IN (SELECT ModuleId FROM dbo.Modules WHERE ModuleName IN ('Reporting','Reports')));
DELETE FROM dbo.FarmHouseModules WHERE ModuleId IN (SELECT ModuleId FROM dbo.Modules WHERE ModuleName IN ('Reporting','Reports'));
DELETE FROM dbo.RoleModules WHERE ModuleId IN (SELECT ModuleId FROM dbo.Modules WHERE ModuleName IN ('Reporting','Reports'));
UPDATE m SET m.[ModuleName]=j.[ModuleName],m.[DisplayName]=j.[DisplayName],m.[Icon]=j.[Icon],m.[Route]=j.[Route],m.[DisplayOrder]=j.[DisplayOrder],m.[IsActive]=j.[IsActive],m.[CreatedDate]=j.[CreatedDate],m.[CreatedBy]=j.[CreatedBy],m.[ModifiedDate]=j.[ModifiedDate],m.[ModifiedBy]=j.[ModifiedBy] FROM dbo.Modules m CROSS APPLY OPENJSON((SELECT BeforeJson FROM dbo.__Phase2ReportingBackup WHERE ObjectName='Modules')) WITH ([ModuleId] int,[ModuleName] nvarchar(100),[DisplayName] nvarchar(200),[Icon] nvarchar(100),[Route] nvarchar(200),[DisplayOrder] int,[IsActive] bit,[CreatedDate] datetime2,[CreatedBy] int,[ModifiedDate] datetime2,[ModifiedBy] int) j WHERE m.ModuleId=j.ModuleId;
SET IDENTITY_INSERT dbo.RoleModules ON;
INSERT dbo.RoleModules([RoleModuleId],[RoleId],[ModuleId],[IsActive],[CreatedDate],[CreatedBy],[ModifiedDate],[ModifiedBy]) SELECT [RoleModuleId],[RoleId],[ModuleId],[IsActive],[CreatedDate],[CreatedBy],[ModifiedDate],[ModifiedBy] FROM OPENJSON((SELECT BeforeJson FROM dbo.__Phase2ReportingBackup WHERE ObjectName='RoleModules')) WITH ([RoleModuleId] int,[RoleId] int,[ModuleId] int,[IsActive] bit,[CreatedDate] datetime2,[CreatedBy] int,[ModifiedDate] datetime2,[ModifiedBy] int);
SET IDENTITY_INSERT dbo.RoleModules OFF;
SET IDENTITY_INSERT dbo.FarmHouseModules ON;
INSERT dbo.FarmHouseModules([FarmHouseModuleId],[FarmHouseId],[ModuleId],[IsEnabled],[IsDeleted],[CreatedDate],[CreatedBy],[ModifiedDate],[ModifiedBy]) SELECT [FarmHouseModuleId],[FarmHouseId],[ModuleId],[IsEnabled],[IsDeleted],[CreatedDate],[CreatedBy],[ModifiedDate],[ModifiedBy] FROM OPENJSON((SELECT BeforeJson FROM dbo.__Phase2ReportingBackup WHERE ObjectName='FarmHouseModules')) WITH ([FarmHouseModuleId] int,[FarmHouseId] int,[ModuleId] int,[IsEnabled] bit,[IsDeleted] bit,[CreatedDate] datetime2,[CreatedBy] int,[ModifiedDate] datetime2,[ModifiedBy] int);
SET IDENTITY_INSERT dbo.FarmHouseModules OFF;
SET IDENTITY_INSERT dbo.RoleModulePermissions ON;
INSERT dbo.RoleModulePermissions([RoleModulePermissionId],[RoleModuleId],[PermissionId],[IsAllowed],[IsActive],[IsDeleted],[CreatedDate],[CreatedBy],[ModifiedDate],[ModifiedBy]) SELECT [RoleModulePermissionId],[RoleModuleId],[PermissionId],[IsAllowed],[IsActive],[IsDeleted],[CreatedDate],[CreatedBy],[ModifiedDate],[ModifiedBy] FROM OPENJSON((SELECT BeforeJson FROM dbo.__Phase2ReportingBackup WHERE ObjectName='RoleModulePermissions')) WITH ([RoleModulePermissionId] int,[RoleModuleId] int,[PermissionId] int,[IsAllowed] bit,[IsActive] bit,[IsDeleted] bit,[CreatedDate] datetime2,[CreatedBy] int,[ModifiedDate] datetime2,[ModifiedBy] int);
SET IDENTITY_INSERT dbo.RoleModulePermissions OFF;
DROP TABLE dbo.__Phase2ReportingBackup;
